using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Driver {
    public record Input(string name, int position) {
    }
    public sealed class Node {
        public string symbol, mark;
        public List<Node> children = new();
        public Node(string symbol) {
            this.symbol = symbol;
        }
    }
    public record StackEntry(string symbol, Node node) {
    }
    public record Trace(int step, List<string> stack, List<string> input, string action) {
    }
    public record Event(int step, string kind, string symbol, string token, int position) {
    }
    public sealed class Result {
        public Node root;
        public List<Trace> trace = new();
        public List<int> leftParse = new();
        public List<Event> errors = new();
        public int predicts, matches, skip, pop, missing, maxStack;
    }
    public static Result Parse(List<Input> original, GrammarParser.Grammar grammar, FirstFollow.Sets sets,
                               Table.Result table) {
        List<Input> input = new(original);
        input.Add(new Input("$", original.Count + 1));
        Result result = new Result();
        result.root = new Node(grammar.start);
        List<StackEntry> stack = new();
        stack.Add(new StackEntry("$", null));
        stack.Add(new StackEntry(grammar.start, result.root));
        int cursor = 0, step = 0;
        while (true) {
            step++;
            StackEntry entry = stack[^1];
            string top = entry.symbol;
            Input token = input[cursor];
            string current = token.name;
            result.maxStack = Math.Max(result.maxStack, stack.Count);
            List<string> beforeStack = new(), beforeInput = new();
            foreach (StackEntry value in stack)
                beforeStack.Add(value.symbol);
            for (int i = cursor; i < input.Count; i++)
                beforeInput.Add(input[i].name);
            string action;
            bool terminate = false;
            Event errorEvent = null;
            if (top.Equals("$") && current.Equals("$")) {
                action = "accept";
                terminate = true;
            } else if (top.Equals("$")) {
                action = "error: skip " + current;
                errorEvent = new Event(step, "skip", top, current, token.position);
                cursor++;
                result.skip++;
            } else if (!GrammarParser.Nonterminal(top)) {
                if (top.Equals(current)) {
                    action = "match " + current;
                    stack.RemoveAt(stack.Count - 1);
                    cursor++;
                    result.matches++;
                } else {
                    action = "error: missing " + top;
                    entry.node.mark = "missing";
                    stack.RemoveAt(stack.Count - 1);
                    result.missing++;
                    errorEvent = new Event(step, "missing", top, current, token.position);
                }
            } else if (table.choices.ContainsKey(new Table.Cell(top, current))) {
                int number = table.choices[new Table.Cell(top, current)];
                Table.Production production = table.productions[number - 1];
                action = "predict " + number + ": " + production.Notation();
                result.leftParse.Add(number);
                stack.RemoveAt(stack.Count - 1);
                if (production.rhs.Count == 0)
                    entry.node.children.Add(new Node("%empty"));
                else {
                    List<Node> children = new();
                    foreach (string symbol in production.rhs)
                        children.Add(new Node(symbol));
                    entry.node.children.AddRange(children);
                    for (int i = children.Count - 1; i >= 0; i--)
                        stack.Add(new StackEntry(children[i].symbol, children[i]));
                }
                result.predicts++;
            } else if (current.Equals("$") || sets.follow[top].Contains(current)) {
                action = "error: pop " + top;
                entry.node.mark = "error";
                stack.RemoveAt(stack.Count - 1);
                result.pop++;
                errorEvent = new Event(step, "pop", top, current, token.position);
            } else {
                action = "error: skip " + current;
                cursor++;
                result.skip++;
                errorEvent = new Event(step, "skip", top, current, token.position);
            }
            result.trace.Add(new Trace(step, beforeStack, beforeInput, action));
            if (errorEvent != null)
                result.errors.Add(errorEvent);
            if (terminate)
                return result;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class FirstFollow {
    public static bool Include<T>(this HashSet<T> set, IEnumerable<T> values) {
        int count = set.Count;
        set.UnionWith(values);
        return set.Count != count;
    }
    public static List<string> TerminalOrder(IEnumerable<string> terminals) {
        List<string> result = new();
        bool end = false;
        foreach (string terminal in terminals)
            if (terminal.Equals("$"))
                end = true;
            else
                result.Add(terminal);
        result.Sort(StringComparer.Ordinal);
        if (end)
            result.Add("$");
        return result;
    }
    public static HashSet<string> Terminals(GrammarParser.Grammar grammar) {
        HashSet<string> result = new();
        foreach (string lhs in grammar.order)
            foreach (List<string> rhs in grammar.rules[lhs])
                foreach (string symbol in rhs)
                    if (!GrammarParser.Nonterminal(symbol))
                        result.Add(symbol);
        return result;
    }
    public record Sequence(HashSet<string> first, bool empty) {
    }
    public sealed class Sets {
        public Dictionary<string, bool> nullable = new();
        public Dictionary<string, HashSet<string>> first = new(), follow = new();
        public int nullablePasses, firstPasses, followPasses;
        public List<string> terminals;
    }
    public static Sequence OfSequence(List<string> rhs, Sets sets) {
        HashSet<string> result = new();
        foreach (string symbol in rhs) {
            if (!GrammarParser.Nonterminal(symbol)) {
                result.Add(symbol);
                return new Sequence(result, false);
            }
            result.UnionWith(sets.first[symbol]);
            if (!sets.nullable[symbol])
                return new Sequence(result, false);
        }
        return new Sequence(result, true);
    }
    public static Sets Analyze(GrammarParser.Grammar grammar) {
        Sets sets = new Sets();
        foreach (string lhs in grammar.order) {
            sets.nullable[lhs] = false;
            sets.first[lhs] = new();
            sets.follow[lhs] = new();
        }
        sets.follow[grammar.start].Add("$");
        bool changed;
        do {
            sets.nullablePasses++;
            changed = false;
            foreach (string lhs in grammar.order)
                if (!sets.nullable[lhs])
                    foreach (List<string> rhs in grammar.rules[lhs]) {
                        bool empty = true;
                        foreach (string symbol in rhs)
                            if (!GrammarParser.Nonterminal(symbol) || !sets.nullable[symbol])
                                empty = false;
                        if (empty) {
                            sets.nullable[lhs] = true;
                            changed = true;
                            break;
                        }
                    }
        } while (changed);
        do {
            sets.firstPasses++;
            changed = false;
            foreach (string lhs in grammar.order)
                foreach (List<string> rhs in grammar.rules[lhs])
                    if (sets.first[lhs].Include(OfSequence(rhs, sets).first))
                        changed = true;
        } while (changed);
        do {
            sets.followPasses++;
            changed = false;
            foreach (string lhs in grammar.order)
                foreach (List<string> rhs in grammar.rules[lhs])
                    for (int i = 0; i < rhs.Count; i++) {
                        string symbol = rhs[i];
                        if (!GrammarParser.Nonterminal(symbol))
                            continue;
                        Sequence suffix = OfSequence(rhs.GetRange(i + 1, rhs.Count - (i + 1)), sets);
                        HashSet<string> more = new(suffix.first);
                        if (suffix.empty)
                            more.UnionWith(sets.follow[lhs]);
                        if (sets.follow[symbol].Include(more))
                            changed = true;
                    }
        } while (changed);
        sets.terminals = TerminalOrder(Terminals(grammar));
        return sets;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class GrammarParser {
    public sealed class Grammar {
        public List<string> order = new();
        public Dictionary<string, List<List<string>>> rules = new();
        public string start;
        public HashSet<string> declared = new();
        public bool hasDeclaration;
        public Dictionary<string, int> words = new();
        public List<string> diagnostics = new();
    }
    public record Token(string kind, string value, int start, int end) {
    }
    public record Parsed(string kind, string lhs, List<List<string>> alternatives, List<string> words,
                         int error) {
    }
    public static bool Nonterminal(string symbol) {
        return symbol.StartsWith("<") && symbol.EndsWith(">");
    }
    public static bool Letter(char c) {
        return c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z';
    }
    public static bool Word(char c) {
        return Letter(c) || c >= '0' && c <= '9' || c == '_';
    }
    public static List<Token> Lex(string line) {
        List<Token> tokens = new();
        int i = 0;
        while (i < line.Length) {
            char c = line[i];
            if (c == ' ') {
                i++;
                continue;
            }
            if (c == '#')
                break;
            int start = i;
            string kind = "invalid", value = c.ToString();
            if (c == '<') {
                int j = i + 1;
                if (j < line.Length && Letter(line[j])) {
                    j++;
                    while (j < line.Length && Word(line[j]))
                        j++;
                    if (j < line.Length && line[j] == '>') {
                        kind = "nonterminal";
                        i = j + 1;
                        value = line.Substring(start, i - (start));
                    }
                }
            } else if (c == '"') {
                int j = i + 1;
                while (j < line.Length && line[j] != ' ' && line[j] != '"')
                    j++;
                if (j > i + 1 && j < line.Length && line[j] == '"') {
                    kind = "terminal";
                    value = line.Substring(i + 1, j - (i + 1));
                    i = j + 1;
                }
            } else if (Letter(c)) {
                int j = i + 1;
                while (j < line.Length && Word(line[j]))
                    j++;
                kind = "word";
                i = j;
                value = line.Substring(start, i - (start));
            } else if (line.IndexOf("::=", i, StringComparison.Ordinal) == i) {
                kind = "definition";
                value = "::=";
                i += 3;
            } else if (c == '|') {
                kind = "separator";
                value = "|";
                i++;
            } else if (c == '%') {
                int j = i + 1;
                while (j < line.Length && Letter(line[j]))
                    j++;
                string directive = line.Substring(i + 1, j - (i + 1));
                if (new string[] { "empty", "start", "token" }.Contains(directive)) {
                    kind = "directive";
                    value = "%" + directive;
                    i = j;
                }
            }
            if (kind.Equals("invalid"))
                i = start + 1;
            tokens.Add(new Token(kind, value, start + 1, i));
            if (kind.Equals("invalid"))
                break;
        }
        return tokens;
    }
    public static int Error(List<Token> tokens, int cursor) {
        return cursor < tokens.Count ? tokens[cursor].start : tokens[^1].end + 1;
    }
    public static Parsed Bad(List<Token> tokens, int cursor) {
        return new Parsed("", null, null, null, Error(tokens, cursor));
    }
    public static bool Symbol(Token token) {
        return new string[] { "nonterminal", "terminal", "word" }.Contains(token.kind);
    }
    public static Parsed Alternatives(List<Token> tokens, int cursor, string kind, string lhs) {
        List<List<string>> alternatives = new();
        while (true) {
            if (cursor >= tokens.Count)
                return Bad(tokens, cursor);
            Token first = tokens[cursor];
            List<string> alternative = new();
            if (first.kind.Equals("directive") && first.value.Equals("%empty")) {
                cursor++;
                if (cursor < tokens.Count && !tokens[cursor].kind.Equals("separator"))
                    return Bad(tokens, cursor);
            } else if (Symbol(first)) {
                while (cursor < tokens.Count && Symbol(tokens[cursor]))
                    alternative.Add(tokens[cursor++].value);
            } else
                return Bad(tokens, cursor);
            alternatives.Add(alternative);
            if (cursor >= tokens.Count)
                return new Parsed(kind, lhs, alternatives, null, 0);
            if (!tokens[cursor].kind.Equals("separator"))
                return Bad(tokens, cursor);
            cursor++;
        }
    }
    public static Parsed Line(List<Token> tokens) {
        if (tokens.Count == 0)
            return new Parsed("blank", null, null, null, 0);
        Token first = tokens[0];
        if (first.kind.Equals("nonterminal")) {
            if (tokens.Count < 2)
                return Bad(tokens, tokens.Count);
            if (!tokens[1].kind.Equals("definition"))
                return Bad(tokens, 1);
            return Alternatives(tokens, 2, "rule", first.value);
        }
        if (first.kind.Equals("separator"))
            return Alternatives(tokens, 1, "continuation", null);
        if (first.kind.Equals("directive") && first.value.Equals("%start")) {
            if (tokens.Count < 2)
                return Bad(tokens, tokens.Count);
            if (!tokens[1].kind.Equals("nonterminal"))
                return Bad(tokens, 1);
            if (tokens.Count > 2)
                return Bad(tokens, 2);
            return new Parsed("start", tokens[1].value, null, null, 0);
        }
        if (first.kind.Equals("directive") && first.value.Equals("%token")) {
            if (tokens.Count < 2)
                return Bad(tokens, tokens.Count);
            List<string> words = new();
            for (int i = 1; i < tokens.Count; i++) {
                if (!tokens[i].kind.Equals("word"))
                    return Bad(tokens, i);
                words.Add(tokens[i].value);
            }
            return new Parsed("declaration", null, null, words, 0);
        }
        return Bad(tokens, 0);
    }
    public static string Notation(List<string> symbols) {
        return symbols.Count == 0 ? "%empty" : string.Join(" ", symbols);
    }
    public static string Production(string lhs, List<string> rhs) {
        return lhs + " -> " + Notation(rhs);
    }
    public static Grammar Parse(List<string> lines) {
        Grammar grammar = new Grammar();
        string attachment = null;
        for (int i = 0; i < lines.Count; i++) {
            int number = i + 1;
            List<Token> tokens = Lex(lines[i]);
            Parsed parsed = Line(tokens);
            if (parsed.error > 0) {
                grammar.diagnostics.Add("line " + number + ": syntax error at column " + parsed.error);
                attachment = null;
                continue;
            }
            if (parsed.kind.Equals("blank"))
                continue;
            string lhs = parsed.lhs;
            if (parsed.kind.Equals("rule")) {
                attachment = lhs;
                if (!grammar.rules.ContainsKey(lhs)) {
                    grammar.order.Add(lhs);
                    grammar.rules[lhs] = new();
                }
            } else if (parsed.kind.Equals("continuation")) {
                if (attachment == null) {
                    grammar.diagnostics.Add("line " + number + ": continuation without a rule");
                    continue;
                }
                lhs = attachment;
            } else if (parsed.kind.Equals("start")) {
                attachment = null;
                if (grammar.start == null)
                    grammar.start = lhs;
                else
                    grammar.diagnostics.Add("line " + number + ": duplicate %start");
            } else {
                attachment = null;
                grammar.hasDeclaration = true;
                grammar.declared.UnionWith(parsed.words);
            }
            if (parsed.kind.Equals("rule") || parsed.kind.Equals("continuation")) {
                foreach (Token token in tokens)
                    if (token.kind.Equals("word"))
                        grammar.words.TryAdd(token.value, number);
                foreach (List<string> alternative in parsed.alternatives) {
                    if (grammar.rules[lhs].Any(old => old.SequenceEqual(alternative)))
                        grammar.diagnostics.Add("line " + number + ": duplicate alternative " +
                                                Production(lhs, alternative));
                    else
                        grammar.rules[lhs].Add(alternative);
                }
            }
        }
        if (grammar.start == null)
            grammar.start = grammar.order[0];
        return grammar;
    }
    public static Grammar Copy(Grammar original) {
        Grammar result = new Grammar();
        result.order.AddRange(original.order);
        result.start = original.start;
        foreach (string lhs in original.order) {
            List<List<string>> alternatives = new();
            foreach (List<string> rhs in original.rules[lhs])
                alternatives.Add(new(rhs));
            result.rules[lhs] = alternatives;
        }
        return result;
    }
}

using System.Numerics;
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;

public static class Program {
    public static string Repeat(this string text, int count) => string.Concat(Enumerable.Repeat(text, count));
    public static GrammarParser.Grammar parsed, cleaned, eliminated, factored, grammar;
    public static List<string> diagnostics = new(), eliminationLog, factorLog, unreachableLog = new();
    public static FirstFollow.Sets sets;
    public static Table.Result table;
    public static int beforeConflicts;
    public static Dictionary<string, Metric> lengths = new(), costs = new();
    public static Dictionary<string, List<string>> words = new(), leftContext = new(), rightContext = new();
    public record Metric(BigInteger length, int height) : IComparable<Metric> {
        public int CompareTo(Metric m) {
            int c = length.CompareTo(m.length);
            return c != 0 ? c : height.CompareTo(m.height);
        }
    }
    public static BigInteger Plus(BigInteger a, BigInteger b) {
        return a + b;
    }
    public static string List<T>(string heading, IEnumerable<T> values) {
        string line = heading;
        foreach (Object value in values)
            line += " " + value;
        return line;
    }
    public static List<string> Lines(string name) {
        return File.ReadAllLines(Path.Combine("input", name), Encoding.ASCII).ToList();
    }
    public static void Write(string name, List<string> lines) {
        File.WriteAllText(Path.Combine("output", name), string.Join("\n", lines) + "\n", Encoding.ASCII);
    }
    public static HashSet<string> Reachable(GrammarParser.Grammar g) {
        HashSet<string> seen = new();
        Queue<string> queue = new();
        queue.Enqueue(g.start);
        seen.Add(g.start);
        while (queue.Count != 0) {
            string lhs = queue.Dequeue();
            foreach (List<string> rhs in g.rules[lhs])
                foreach (string symbol in rhs)
                    if (GrammarParser.Nonterminal(symbol) && seen.Add(symbol))
                        queue.Enqueue(symbol);
        }
        return seen;
    }
    public static string FirstRemoved(List<string> rhs, HashSet<string> removed) {
        foreach (string symbol in rhs)
            if (removed.Contains(symbol))
                return symbol;
        return null;
    }
    public static void FilterAlternatives(GrammarParser.Grammar g, HashSet<string> removed, string reason) {
        foreach (string lhs in g.order) {
            List<List<string>> keep = new();
            foreach (List<string> rhs in g.rules[lhs]) {
                string symbol = FirstRemoved(rhs, removed);
                if (symbol == null)
                    keep.Add(rhs);
                else
                    diagnostics.Add("removed " + GrammarParser.Production(lhs, rhs) + " (" + reason + " " +
                                    symbol + ")");
            }
            g.rules[lhs] = keep;
        }
    }
    public static void Remove(GrammarParser.Grammar g, HashSet<string> removed) {
        g.order.RemoveAll(symbol => removed.Contains(symbol));
        foreach (string symbol in removed)
            g.rules.Remove(symbol);
    }
    public static GrammarParser.Grammar Clean() {
        GrammarParser.Grammar g = GrammarParser.Copy(parsed);
        if (parsed.hasDeclaration)
            foreach (string word in FirstFollow.TerminalOrder(parsed.words.Keys))
                if (!parsed.declared.Contains(word))
                    diagnostics.Add("undeclared terminal " + word + " at line " + parsed.words[word]);
        HashSet<string> undefined = new();
        foreach (string lhs in g.order)
            foreach (List<string> rhs in g.rules[lhs])
                foreach (string symbol in rhs)
                    if (GrammarParser.Nonterminal(symbol) && !g.rules.ContainsKey(symbol))
                        undefined.Add(symbol);
        List<string> sorted = new(undefined);
        sorted.Sort((a, b) =>
                        string.CompareOrdinal(a.Substring(1, a.Length - 2), b.Substring(1, b.Length - 2)));
        foreach (string symbol in sorted)
            diagnostics.Add("undefined nonterminal " + symbol);
        FilterAlternatives(g, undefined, "undefined");
        HashSet<string> productive = new();
        bool changed;
        do {
            changed = false;
            foreach (string lhs in g.order)
                if (!productive.Contains(lhs))
                    foreach (List<string> rhs in g.rules[lhs]) {
                        bool valid = true;
                        foreach (string symbol in rhs)
                            if (GrammarParser.Nonterminal(symbol) && !productive.Contains(symbol))
                                valid = false;
                        if (valid) {
                            productive.Add(lhs);
                            changed = true;
                            break;
                        }
                    }
        } while (changed);
        HashSet<string> removed = new();
        foreach (string lhs in g.order)
            if (!productive.Contains(lhs)) {
                removed.Add(lhs);
                diagnostics.Add("unproductive nonterminal " + lhs);
            }
        Remove(g, removed);
        FilterAlternatives(g, removed, "unproductive");
        HashSet<string> reachable = Reachable(g);
        removed = new();
        foreach (string lhs in g.order)
            if (!reachable.Contains(lhs)) {
                removed.Add(lhs);
                diagnostics.Add("unreachable nonterminal " + lhs);
            }
        Remove(g, removed);
        return g;
    }
    public static void LeftRecursion() {
        foreach (string origin in cleaned.order) {
            Queue<string> queue = new();
            Dictionary<string, string> parent = new();
            HashSet<string> seen = new();
            queue.Enqueue(origin);
            seen.Add(origin);
            string last = null;
            while (queue.Count != 0 && last == null) {
                string current = queue.Dequeue();
                foreach (List<string> rhs in cleaned.rules[current]) {
                    if (rhs.Count == 0)
                        continue;
                    string first = rhs[0];
                    if (first.Equals(origin)) {
                        last = current;
                        break;
                    }
                    if (GrammarParser.Nonterminal(first) && seen.Add(first)) {
                        parent[first] = current;
                        queue.Enqueue(first);
                    }
                }
            }
            if (last != null) {
                List<string> path = new();
                for (string current = last; !current.Equals(origin); current = parent[current])
                    path.Add(current);
                path.Reverse();
                path.Insert(0, origin);
                path.Add(origin);
                diagnostics.Add("left recursion: " + string.Join(" -> ", path));
            }
        }
    }
    public static void Prepare() {
        diagnostics.AddRange(parsed.diagnostics);
        cleaned = Clean();
        LeftRecursion();
        FirstFollow.Sets before = FirstFollow.Analyze(cleaned);
        beforeConflicts = Table.Build(cleaned, before).conflicts.Count;
        Transform.Result elimination = Transform.Eliminate(cleaned);
        eliminated = elimination.grammar;
        eliminationLog = elimination.log;
        Transform.Result factoring = Transform.Factor(eliminated);
        factored = factoring.grammar;
        factorLog = factoring.log;
        grammar = GrammarParser.Copy(factored);
        HashSet<string> reachable = Reachable(grammar), removed = new();
        foreach (string lhs in grammar.order)
            if (!reachable.Contains(lhs)) {
                removed.Add(lhs);
                unreachableLog.Add("remove unreachable " + lhs);
                diagnostics.Add("unreachable after transformation " + lhs);
            }
        Remove(grammar, removed);
        sets = FirstFollow.Analyze(grammar);
        table = Table.Build(grammar, sets);
        if (parsed.hasDeclaration) {
            HashSet<string> unused = new(parsed.declared);
            unused.ExceptWith(sets.terminals);
            foreach (string terminal in FirstFollow.TerminalOrder(unused))
                diagnostics.Add("unused token " + terminal);
        }
        Shortest();
        Contexts();
    }
    public static Metric AlternativeMetric(List<string> rhs) {
        BigInteger length = BigInteger.Zero;
        int height = 1;
        foreach (string symbol in rhs)
            if (GrammarParser.Nonterminal(symbol)) {
                Metric child = lengths.GetValueOrDefault(symbol);
                if (child == null)
                    return null;
                length = Plus(length, child.length);
                height = Math.Max(height, child.height + 1);
            } else
                length = Plus(length, BigInteger.One);
        return new Metric(length, height);
    }
    public static void Shortest() {
        bool changed;
        do {
            changed = false;
            foreach (string lhs in grammar.order)
                foreach (List<string> rhs in grammar.rules[lhs]) {
                    Metric candidate = AlternativeMetric(rhs), old = lengths.GetValueOrDefault(lhs);
                    if (candidate != null && (old == null || candidate.CompareTo(old) < 0)) {
                        lengths[lhs] = candidate;
                        changed = true;
                    }
                }
        } while (changed);
        foreach (string lhs in grammar.order)
            Word(lhs);
    }
    public static List<string> Word(string lhs) {
        if (words.ContainsKey(lhs))
            return words[lhs];
        foreach (List<string> rhs in grammar.rules[lhs])
            if (AlternativeMetric(rhs).Equals(lengths[lhs])) {
                List<string> result = Sentence(rhs);
                words[lhs] = result;
                return result;
            }
        throw new InvalidOperationException();
    }
    public static List<string> Sentence(List<string> symbols) {
        List<string> result = new();
        foreach (string symbol in symbols)
            if (GrammarParser.Nonterminal(symbol))
                result.AddRange(Word(symbol));
            else
                result.Add(symbol);
        return result;
    }
    public static Metric ContextMetric(Table.Production production, int occurrence) {
        Metric parent = costs.GetValueOrDefault(production.lhs);
        if (parent == null)
            return null;
        BigInteger length = parent.length;
        for (int i = 0; i < production.rhs.Count; i++)
            if (i != occurrence) {
                string symbol = production.rhs[i];
                length =
                    Plus(length, GrammarParser.Nonterminal(symbol) ? lengths[symbol].length : BigInteger.One);
            }
        return new Metric(length, parent.height + 1);
    }
    public static void Contexts() {
        costs[grammar.start] = new Metric(BigInteger.Zero, 0);
        bool changed;
        do {
            changed = false;
            foreach (Table.Production production in table.productions)
                for (int i = 0; i < production.rhs.Count; i++) {
                    string symbol = production.rhs[i];
                    if (!GrammarParser.Nonterminal(symbol) || symbol.Equals(grammar.start))
                        continue;
                    Metric candidate = ContextMetric(production, i), old = costs.GetValueOrDefault(symbol);
                    if (candidate != null && (old == null || candidate.CompareTo(old) < 0)) {
                        costs[symbol] = candidate;
                        changed = true;
                    }
                }
        } while (changed);
        leftContext[grammar.start] = new();
        rightContext[grammar.start] = new();
        foreach (string lhs in grammar.order)
            Context(lhs);
    }
    public static void Context(string lhs) {
        if (leftContext.ContainsKey(lhs))
            return;
        foreach (Table.Production production in table.productions)
            for (int i = 0; i < production.rhs.Count; i++)
                if (production.rhs[i].Equals(lhs) && ContextMetric(production, i) != null &&
                    ContextMetric(production, i).Equals(costs[lhs])) {
                    Context(production.lhs);
                    List<string> left = new(leftContext[production.lhs]);
                    left.AddRange(Sentence(production.rhs.GetRange(0, i - (0))));
                    List<string> right =
                        Sentence(production.rhs.GetRange(i + 1, production.rhs.Count - (i + 1)));
                    right.AddRange(rightContext[production.lhs]);
                    leftContext[lhs] = left;
                    rightContext[lhs] = right;
                    return;
                }
    }
    public static List<string> Example(Table.Production production) {
        List<string> result = new(leftContext[production.lhs]);
        result.AddRange(Sentence(production.rhs));
        result.AddRange(rightContext[production.lhs]);
        return result;
    }
    public static string Summary(GrammarParser.Grammar g) {
        int productions = 0, empty = 0, unit = 0;
        foreach (string lhs in g.order)
            foreach (List<string> rhs in g.rules[lhs]) {
                productions++;
                if (rhs.Count == 0)
                    empty++;
                if (rhs.Count == 1 && GrammarParser.Nonterminal(rhs[0]))
                    unit++;
            }
        return "start=" + g.start + " nonterminals=" + g.order.Count +
               " terminals=" + FirstFollow.Terminals(g).Count + " productions=" + productions +
               " empty=" + empty + " unit=" + unit;
